for lang, idx in (("en", 0), ("pt-BR", 1)):
    out = {"WONDER": {}}
    for k, v in T.items():
        node = out["WONDER"]
        parts = k.split(".")
        for part in parts[:-1]:
            node = node.setdefault(part, {})
        node[parts[-1]] = v[idx]
    with open(os.path.join(ROOT, "lang", f"{lang}.json"), "w") as fh:
        json.dump(out, fh, indent=2, ensure_ascii=False)
print("lang ok", len(T))
